  ('social', 'ป.6', '2', 'หน้าที่พลเมือง วัฒนธรรม และการดำเนินชีวิตในสังคม', 'ส 2.2', 'ส 2.2 ป.6/1', 'เปรียบเทียบบทบาท หน้าที่ขององค์กรปกครอง ส่วนท้องถิ่นและรัฐบาล', 'ระหว่างทาง', 196),
  ('social', 'ป.6', '2', 'หน้าที่พลเมือง วัฒนธรรม และการดำเนินชีวิตในสังคม', 'ส 2.2', 'ส 2.2 ป.6/2', 'มีส่วนร่วม ในกิจกรรมต่าง ๆ ที่ส่งเสริม ประชาธิปไตยในท้องถิ่นและ ประเทศ', 'ปลายทาง', 197),
  ('social', 'ป.6', '2', 'หน้าที่พลเมือง วัฒนธรรม และการดำเนินชีวิตในสังคม', 'ส 2.2', 'ส 2.2 ป.6/3', 'อภิปรายบทบาท ความสำคัญในการใช้สิทธิ ออกเสียงเลือกตั้งตามระบอบประชาธิปไตย', 'ระหว่างทาง', 198),
  ('social', 'ป.6', '3', 'เศรษฐศาสตร์', 'ส 3.1', 'ส 3.1 ป.6/1', 'อธิบายบทบาทของผู้ผลิตที่มีความรับผิดชอบ', 'ระหว่างทาง', 199),
  ('social', 'ป.6', '3', 'เศรษฐศาสตร์', 'ส 3.1', 'ส 3.1 ป.6/2', 'อธิบายบทบาทของผู้บริโภคที่รู้เท่าทัน', 'ระหว่างทาง', 200),
  ('social', 'ป.6', '3', 'เศรษฐศาสตร์', 'ส 3.1', 'ส 3.1 ป.6/3', 'บอกวิธีและประโยชน์ ของการใช้ทรัพยากรอย่างยั่งยืน', 'ปลายทาง', 201),
  ('social', 'ป.6', '3', 'เศรษฐศาสตร์', 'ส 3.2', 'ส 3.2 ป.6/1', 'อธิบายความสัมพันธ์ ระหว่างผู้ผลิต ผู้บริโภค ธนาคาร และรัฐบาล 23', 'ปลายทาง', 202),
  ('social', 'ป.6', '3', 'เศรษฐศาสตร์', 'ส 3.2', 'ส 3.2 ป.6/2', 'ยกตัวอย่างการรวมกลุ่มทางเศรษฐกิจภายใน ท้องถิ่น', 'ระหว่างทาง', 203),
  ('social', 'ป.6', '4', 'ประวัติศาสตร์', 'ส 4.1', 'ส 4.1 ป.6/1', 'อธิบายความสำคัญของวิธีการทางประวัติศาสตร์ ในการศึกษาเรื่องราวทางประวัติศาสตร์อย่างง่าย ๆ *', 'ระหว่างทาง', 204),
  ('social', 'ป.6', '4', 'ประวัติศาสตร์', 'ส 4.1', 'ส 4.1 ป.6/2', 'นำเสนอข้อมูล จากหลักฐานที่หลากหลายในการ ทำความเข้าใจเรื่องราวสำคัญในอดีต', NULL, 205),
  ('social', 'ป.6', '4', 'ประวัติศาสตร์', 'ส 4.2', 'ส 4.2 ป.6/1', 'อธิบายสภาพสังคม เศรษฐกิจและการเมืองของ ประเทศเพื่อนบ้านในปัจจุบัน', 'ปลายทาง', 206),
  ('social', 'ป.6', '4', 'ประวัติศาสตร์', 'ส 4.2', 'ส 4.2 ป.6/2', 'บอกความสัมพันธ์ของกลุ่มอาเซียน โดยสังเขป', 'ระหว่างทาง', 207),
  ('social', 'ป.6', '4', 'ประวัติศาสตร์', 'ส 4.3', 'ส 4.3 ป.6/1', 'อธิบายพัฒนาการ ของไทยสมัยรัตนโกสินทร์โดยสังเขป', 'ปลายทาง', 208),
  ('social', 'ป.6', '4', 'ประวัติศาสตร์', 'ส 4.3', 'ส 4.3 ป.6/2', 'อธิบายปัจจัยที่ ส่งเสริมความเจริญรุ่งเรืองทาง เศรษฐกิจและการปกครองของไทย สมัยรัตนโกสินทร์', 'ปลายทาง', 209),
  ('social', 'ป.6', '4', 'ประวัติศาสตร์', 'ส 4.3', 'ส 4.3 ป.6/3', 'ยกตัวอย่างผลงานของบุคคลสำคัญด้านต่าง ๆ สมัยรัตนโกสินทร์', 'ระหว่างทาง', 210),
  ('social', 'ป.6', '4', 'ประวัติศาสตร์', 'ส 4.3', 'ส 4.3 ป.6/4', 'อธิบายภูมิปัญญาไทยที่สำคัญสมัยรัตนโกสินทร์ ที่น่าภาคภูมิใจ และควรค่าแก่การอนุรักษ์ไว้ หมายเหตุ * วิธีการทางประวัติศาสตร์เป็นกระบวนการที่ใช้ในการจัดการเรียนรู้เพื่อให้ผู้เรียนเข้าถึงองค์ความรู้ ทางประวัติศาสตร์ ดังนั้น วิธีการทางประวัติศาสตร์จึงระบุไว้ในทุกกลุ่มตัวชี้วัดที่แสดงเนื้อหา ทางประวัติศาสตร์ที่ผู้เรียนควรศึกษา 24', 'ระหว่างทาง', 211),
  ('social', 'ป.6', '5', 'ภูมิศาสตร์', 'ส 5.1', 'ส 5.1 ป.6/1', 'สืบค้นและอธิบายข้อมูลลักษณะทางกายภาพ ของประเทศไทย ด้วยแผนที่ รูปถ่ายทางอากาศ และภาพจาก ดาวเทียม', 'ระหว่างทาง', 212),
  ('social', 'ป.6', '5', 'ภูมิศาสตร์', 'ส 5.1', 'ส 5.1 ป.6/2', 'อธิบายความสัมพันธ์ระหว่างลักษณะทางกายภาพ กับภัยพิบัติในประเทศไทย เพื่อเตรียมพร้อมรับมือภัยพิบัติ', 'ระหว่างทาง', 213),
  ('social', 'ป.6', '5', 'ภูมิศาสตร์', 'ส 5.2', 'ส 5.2 ป.6/1', 'วิเคราะห์ปฏิสัมพันธ์ ระหว่างสิ่งแวดล้อมทางกายภาพ กับลักษณะกิจกรรมทางเศรษฐกิจ และสังคมในประเทศไทย', 'ปลายทาง', 214),
  ('social', 'ป.6', '5', 'ภูมิศาสตร์', 'ส 5.2', 'ส 5.2 ป.6/2', 'วิเคราะห์การเปลี่ยนแปลงทางกายภาพของ ประเทศไทยในอดีตกับปัจจุบัน และผลที่เกิดขึ้นจาก การเปลี่ยนแปลง', 'ระหว่างทาง', 215),
  ('social', 'ป.6', '5', 'ภูมิศาสตร์', 'ส 5.2', 'ส 5.2 ป.6/3', 'นำเสนอตัวอย่าง ที่สะท้อนให้เห็นผลจากการรักษา และทำลายทรัพยากร และ สิ่งแวดล้อม และเสนอแนวทาง ในการจัดการที่ยั่งยืนในประเทศไทย', 'ปลายทาง', 216)
